\begin{proof}
Let $\varphi_X(t) = \mb{E}e^{itX}$ and $\varphi(t) = \mb{E}e^{it\mc{Z}}$. By Fourier inversion on lattices and by Fourier inversion on $\mb{R}$, we have for $x\in\mc{L}$ that
\[\mb{P}[X=x] = \frac{\beta}{2\pi}\int_{-\pi/\beta}^{\pi/\beta}\varphi_X(t)e^{-itx}dt,\qquad\mc{N}(x) = \frac{1}{2\pi}\int_{-\infty}^\infty\varphi(t)e^{-itx}dt.\]
Therefore
\begin{align*}
|\beta\mc{N}(x)-\mb{P}[X=x]|&=\frac{\beta}{2\pi}\bigg|\int_{-\infty}^\infty\varphi(t)e^{-itx}dt-\int_{-\pi/\beta}^{\pi/\beta}\varphi_X(t)e^{-itx}dt\bigg|\\
&\le\frac{\beta}{2\pi}\int_{-\pi/\beta}^{\pi/\beta}|\varphi(t)-\varphi_X(t)|dt+\frac{\beta}{2\pi}\bigg|\int_{|t|>\pi/\beta}e^{-itx}\varphi(t)dt\bigg|\\
&\le\beta\int_{-\pi/\beta}^{\pi/\beta}|\varphi(t)-\varphi_X(t)|dt +e^{-\pi^2/(2\beta^2)},
\end{align*}
where we used a standard tail bound on Gaussian integrals in the last line. Taking the supremum over $x \in \mc{L}$ completes the proof. 
\end{proof}
